integer n, i, k, x, y, b, fnd
double precision v(5), lo(5), hi(5)
integer fbin(5)
read(5,*) n
lo(1) = 53.35d0;  hi(1) = 1d30;   fbin(1) = 27
lo(2) = 347.67d0; hi(2) = 639.602d0; fbin(2) = 21
lo(3) = 144.783d0; hi(3) = 1d30;  fbin(3) = 32
lo(4) = 203.585d0; hi(4) = 1d30;  fbin(4) = 24
lo(5) = -1d30;    hi(5) = 394.729d0; fbin(5) = 15
do i = 1, n {
  read(5,*) x, y, (v(k), k = 1, 5)
  b = 1
  fnd = 0
  do k = 1, 5 {
    if (fnd == 0) {
      if (v(k) == -9999d0) {
        b = 34
        fnd = 1
      } else if (v(k) < lo(k) | v(k) > hi(k)) {
        b = fbin(k)
        fnd = 1
      }
    }
  }
  write(6,*) x, y, b
}
end

integer n, i, k, x, y, bin, done
integer fb(3), haslo(3), hashi(3)
double precision v(3), lo(3), hi(3)

read(5,*) n

# test table: IDDQ, FMAX, VDD
