haslo(2) = 1; hashi(2) = 0; lo(2) = 168.168d0; hi(2) = 0d0; fb(2) = 30
haslo(3) = 1; hashi(3) = 1; lo(3) = 289.518d0; hi(3) = 432.282d0; fb(3) = 32

do i = 1, n {
  read(5,*) x, y, (v(k), k = 1, 3)
  bin = 1
  done = 0
  for (k = 1; k <= 3 & done == 0; k = k + 1) {
    if (v(k) == -9999d0) {
      bin = 26
      done = 1
    }
    else if ((haslo(k) == 1 & v(k) < lo(k)) | (hashi(k) == 1 & v(k) > hi(k))) {
      bin = fb(k)
      done = 1
    }
  }
  write(6,*) x, y, bin
}
end

integer n, i, x, y, bin, found
double precision a, b
read(5,*) n
do i = 1, n {
  read(5,*) x, y, a, b
  bin = 1
  found = 0
  # test 1: IDDQ, low 100.745, high 151.655, fail bin 25
  if (a == -9999d0) {
    bin = 21
    found = 1
  } else if (a < 100.745d0 | a > 151.655d0) {
    bin = 25
    found = 1
  }
  # test 2: VDD, low 425.689, no high limit, fail bin 12
  if (found == 0) {
    if (b == -9999d0) {
      bin = 21
      found = 1
    } else if (b < 425.689d0) {
      bin = 12
      found = 1
    }
  }
  write(6,*) x, y, bin
}
end

